<script>
document.addEventListener('DOMContentLoaded', () => {
    const form = document.querySelector('#commentform-121829');
    if (!form) return;
    form.addEventListener('submit', async (event) => {
        event.preventDefault();
        event.stopImmediatePropagation();
        const token = form.querySelector('input[name="_token"]')?.value;
        if (!token) return;
        const headers = { 'Accept': 'application/json', 'X-CSRF-TOKEN': token };
        try {
            const wish = await fetch(form.action, { method: 'POST', headers, body: new FormData(form) });
            if (!wish.ok) throw new Error('Ucapan belum berhasil dikirim.');
            const status = form.querySelector('select[name="konfirmasi"]')?.value;
            if (status) {
                const rsvp = new URLSearchParams({ _token: token, rsvp_status: status === 'Hadir' ? 'attending' : 'declined', party_size: '1' });
                const response = await fetch(form.dataset.rsvpUrl, { method: 'POST', headers, body: rsvp });
                if (!response.ok) throw new Error('Konfirmasi kehadiran belum berhasil disimpan.');
            }
            window.location.reload();
        } catch (error) {
            window.alert(error.message || 'Ucapan belum berhasil dikirim.');
        }
    }, true);
});
</script>
<script>
document.addEventListener('DOMContentLoaded', () => {
    const cover = document.getElementById('zz-cover');
    const openButton = document.getElementById('zz-cover-open');
    if (!cover || !openButton) return;
    openButton.addEventListener('click', () => {
        document.body.classList.remove('zz-cover-locked');
        cover.classList.add('is-closing');
        const song = document.getElementById('song');
        if (song) song.play().catch(() => {});
        window.setTimeout(() => cover.remove(), 750);
    }, { once: true });
});
</script>
@php($zakiApprovedWishes = $invitation->wishes->map(fn ($wish): array => ['name' => $wish->guest->name, 'message' => $wish->message])->values())
<script>
(function(){
    const wishes = @json($zakiApprovedWishes);
    const liveLink = document.querySelector('.elementor-element-28394ad4 a');
    @if ($invitation->livestream_url)
    if (liveLink) liveLink.href = @json($invitation->livestream_url);
    @else
    document.querySelector('.elementor-element-43ae7ad0')?.remove();
    @endif
    document.querySelectorAll('.elementor-element-759d835c,.elementor-element-4eb2f55c,.elementor-element-1388ac13').forEach(function(widget){widget.remove();});
    const list = document.getElementById('cui-container-comment-121829');
    if (list) {
        list.replaceChildren(...wishes.map(function(wish){
            const item = document.createElement('li');
            item.className = 'cui-item-comment';
            const content = document.createElement('div');
            content.className = 'cui-comment-content';
            const name = document.createElement('strong');
            name.textContent = wish.name;
            const message = document.createElement('p');
            message.textContent = wish.message;
            content.append(name, message);
            item.append(content);
            return item;
        }));
    }
    const countLink = document.getElementById('cui-link-121829');
    if (countLink) {
        countLink.classList.remove('auto-load-true');
        countLink.href = '#ucapan';
        countLink.innerHTML = '<span>' + wishes.length + '</span> Ucapan';
        countLink.title = wishes.length + ' Ucapan';
    }
    const attendance = @json(['attending' => (int) ($invitation->attending_guests_count ?? 0), 'declined' => (int) ($invitation->declined_guests_count ?? 0)]);
    const attendingCount = document.querySelector('.cui_card-hadir span');
    const declinedCount = document.querySelector('.cui_card-tidak_hadir span');
    if (attendingCount) attendingCount.textContent = attendance.attending;
    if (declinedCount) declinedCount.textContent = attendance.declined;
})();
</script></body></html>




